/* Verify real PixelFX renders were generated by the build, not placeholder sprites. */
import assert from 'node:assert/strict';
import {readFileSync,statSync} from 'node:fs';
import {resolve,join} from 'node:path';
import {inflateSync} from 'node:zlib';
import {JOHTO_PIXELFX_43,JOHTO_APPROVED_3} from '../tools/pokearena/torre2-johto-pixelfx-catalog.js';
import {JOHTO_LAB_REVIEW_4,JOHTO_APPROVED_5} from '../tools/pokearena/torre2-johto-lab-catalog.js';
const dir=resolve(process.env.PREVIEW_ROOT||'_site','arena2d/assets/torre2/johto-pixelfx');
const manifest=JSON.parse(readFileSync(join(dir,'manifest.json'),'utf8'));
// Four moves now render native P2 layers, never the rejected PixelFX sheets.
const remaining=JOHTO_PIXELFX_43.filter(m=>
 !JOHTO_LAB_REVIEW_4.includes(m.id)&&!JOHTO_APPROVED_5.includes(m.id));
assert.equal(JOHTO_PIXELFX_43.length,43);
assert.equal(JOHTO_LAB_REVIEW_4.length,4);
assert.equal(remaining.length,29);
assert.equal(manifest.files.length,remaining.length);
assert.equal(manifest.mode,'visual-only');
assert.equal(manifest.approved,false);
assert.equal(manifest.engine,'P2-native-fourteen-live-plus-PixelFX-unapproved-backlog');
assert.deepEqual(new Set(manifest.files.map(x=>x.id)),new Set(remaining.map(x=>x.id)));
for(const id of JOHTO_LAB_REVIEW_4)assert.ok(!manifest.files.some(x=>x.id===id),id+' rejected rectangular PixelFX must not ship');
for(const id of JOHTO_APPROVED_5)assert.ok(!manifest.files.some(x=>x.id===id),id+' approved VFX was overwritten');
const hashes=new Set();
for(const m of manifest.files){
 const b=readFileSync(join(dir,m.id+'.png'));
 assert.equal(b.subarray(0,8).toString('hex'),'89504e470d0a1a0a');
 assert.equal(b.readUInt32BE(16),1152);
 assert.equal(b.readUInt32BE(20),96);
 assert.ok(statSync(join(dir,m.id+'.png')).size>=512,m.id+': too small');
 assert.ok(m.painted>=12,m.id+': empty sprite');
 const chunks=[];let pos=8;
 while(pos<b.length){
  const n=b.readUInt32BE(pos),kind=b.toString('ascii',pos+4,pos+8);
  if(kind==='IDAT')chunks.push(b.subarray(pos+8,pos+8+n));
  pos+=12+n;
 }
 const raw=inflateSync(Buffer.concat(chunks));
 assert.equal(raw.length,96*(1152*4+1));
 let visible=0;const counts=[];
 for(let f=0;f<12;f++){
  let n=0;
  for(let y=0;y<96;y++)for(let x=0;x<96;x++){
   if(raw[y*(1152*4+1)+1+(f*96+x)*4+3]>90)n++;
  }
  counts.push(n);visible+=n;
 }
 assert.ok(visible>=24,m.id+': no visible frames after PNG compression');
 assert.ok(counts.filter(n=>n>0).length>=3,m.id+': fewer than 3 nonempty frames');
 hashes.add(b.toString('base64'));
}
assert.equal(hashes.size,remaining.length,'Generic copies duplicated PixelFX generated assets');
const version=JSON.parse(readFileSync(resolve(process.env.PREVIEW_ROOT||'_site','arena2d/version.json'),'utf8'));
const output=resolve(process.env.PREVIEW_ROOT||'_site','arena2d',version.modules);
for(const p of ['torre2/torre2-johto-pixelfx-catalog.js','torre2/torre2-johto-pixelfx-runtime.js','torre2/torre2-johto-four-native.js']){
 assert.ok(statSync(join(output,p)).size>100,p);
}
console.log('PASS 29 unapproved PixelFX sheets + fourteen native P2 moves; all fourteen approvals preserved');
